<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Requests\{ProviderRequestRequest,ProviderVerifyRequest}; use App\Models\{Provider,ProviderConnection}; use App\Support\ApiResponse; use Illuminate\Support\Facades\Hash;
class ProviderController extends Controller {use ApiResponse; public function show(){return response()->json(['provider'=>request()->user()->providerConnection?->load('provider')]);} public function requestCode(ProviderRequestRequest $r){$code=(string)random_int(100000,999999);$provider=Provider::where('email',$r->email)->where('is_active',1)->first();ProviderConnection::updateOrCreate(['user_id'=>$r->user()->id],['provider_id'=>$provider?->id,'provider_email'=>$r->email,'verification_code'=>Hash::make($code),'verification_expires_at'=>now()->addMinutes(15),'verified_at'=>null]);$data=['expires_in_minutes'=>15];if(app()->isLocal())$data['development_code']=$code;return $this->success($data,'Verification code created.');} public function verify(ProviderVerifyRequest $r){$c=$r->user()->providerConnection;abort_unless($c&&$c->verification_code,422,'No verification request was found.');abort_if($c->verification_expires_at?->isPast(),422,'The verification code has expired.');abort_unless(Hash::check($r->code,$c->verification_code),422,'The verification code is invalid.');$c->update(['verification_code'=>null,'verification_expires_at'=>null,'verified_at'=>now()]);return $this->success($c->fresh()->load('provider'),'Provider verified successfully.');} public function destroy(){request()->user()->providerConnection()?->delete();return $this->success(null,'Provider connection removed.');}}
